package local.tvmorph.tv;
import org.json.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Provider requests stay native. Credentials/stream URLs never enter the web UI. */
final class Xtream{
 final String server,user,password,format;final JSONObject config;private M3uPlaylist m3u;private PortalSource portal;private boolean classicHttp;private final ProviderPlayback playbackHints=new ProviderPlayback();
 Xtream(JSONObject value)throws Exception{if(value.optString("type").equals("portal")){portal=new PortalSource(value);config=portal.config;server=config.getString("server");user="";password="";format="m3u8";return;}if(value.optString("type").equals("m3u")){m3u=new M3uPlaylist(value);config=m3u.config;server=config.getString("server");user="";password="";format="m3u8";return;}value=XtreamCredentials.normalize(value);config=value;classicHttp="classic".equals(value.optString("providerHttpProfile"));URI uri=new URI(value.getString("server").trim());if(!Arrays.asList("http","https").contains(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null)throw new IOException("اكتب رابط المزوّد كاملًا مع http أو https والمنفذ.");server=uri.toString().replaceAll("/+$","");user=value.optString("username");password=value.optString("password");format=value.optString("format","m3u8").equals("ts")?"ts":"m3u8";if(user.isEmpty()||password.isEmpty()||user.length()>256||password.length()>512)throw new IOException("أدخل اسم المستخدم وكلمة السر داخل التطبيق.");}
 static String enc(String value)throws Exception{return URLEncoder.encode(value,"UTF-8").replace("+","%20");}
 private final Map<String,Object> metadata=new LinkedHashMap<>();private final Map<String,Long> metadataTimes=new HashMap<>();private final Map<String,FutureTask<Object>> metadataRequests=new HashMap<>();private int metadataEpoch;
 synchronized void clearMetadata(){playbackHints.clear();if(m3u!=null)m3u.clear();if(portal!=null)portal.clear();metadataEpoch++;metadata.clear();metadataTimes.clear();metadataRequests.clear();}
 Object request(String action,String key,String id)throws Exception{
  if(!"get_series_info".equals(action)&&!"get_vod_info".equals(action))return networkRequest(action,key,id);
  String cacheKey=action+":"+id;FutureTask<Object> task;int epoch;
  synchronized(this){Long at=metadataTimes.get(cacheKey);if(at!=null&&System.currentTimeMillis()-at<300000)return metadata.get(cacheKey);epoch=metadataEpoch;task=metadataRequests.get(cacheKey);if(task==null){task=new FutureTask<>(()->networkRequest(action,key,id));metadataRequests.put(cacheKey,task);}}
  task.run();try{Object value=task.get();synchronized(this){if(epoch==metadataEpoch&&value.toString().length()<1048576){metadata.put(cacheKey,value);metadataTimes.put(cacheKey,System.currentTimeMillis());while(metadata.size()>4){String oldest=metadata.keySet().iterator().next();metadata.remove(oldest);metadataTimes.remove(oldest);}}}return value;}catch(ExecutionException e){Throwable cause=e.getCause();if(cause instanceof Exception)throw (Exception)cause;throw new IOException("Provider metadata unavailable");}finally{synchronized(this){if(metadataRequests.get(cacheKey)==task)metadataRequests.remove(cacheKey);}}
 }
 Object networkRequest(String action,String key,String id)throws Exception{
  return ProviderHttp.json(requestUrl(action,key,id),classicHttp?"Morph TV/0.4":"MorphTV/1.0",classicHttp?"*/*":"application/json");
 }
 String requestUrl(String action,String key,String id)throws Exception{return server+"/player_api.php?username="+enc(user)+"&password="+enc(password)+(action==null?"":"&action="+enc(action))+(key==null?"":"&"+key+"="+enc(id));}
 ProviderCatalog.Result streamCatalog(String kind,String category,int limit)throws Exception{String action=kind.equals("live")?"get_live_streams":kind.equals("vod")?"get_vod_streams":"get_series";return ProviderHttp.catalog(requestUrl(action,category.isEmpty()?null:"category_id",category),classicHttp?"Morph TV/0.4":"MorphTV/1.0",classicHttp?"*/*":"application/json",in->ProviderCatalog.read(in,limit,item->catalogRow(kind,item)));}
 JSONObject catalogRow(String kind,JSONObject item)throws JSONException{String id=item.optString(kind.equals("series")?"series_id":"stream_id");if(!id.matches("[0-9]{1,14}"))return null;playbackHints.put(server,kind,id,item.optString("container_extension",""),item.optString("direct_source",""),System.currentTimeMillis());return new JSONObject().put("id",id).put("name",item.optString("name","Untitled")).put("icon",rememberImage(kind,id,artwork(item,kind.equals("series")?"cover":"stream_icon"))).put("category",item.optString("category_id")).put("added",item.optLong("added",item.optLong("last_modified",0))).put("kind",kind).put("rating",providerRating(item,"")).put("year",ReleaseYear.from(item)).put("backdrop",wideArtwork(item)).put("ext",item.optString("container_extension","mp4"));}
 JSONObject auth()throws Exception{if(portal!=null)return portal.auth();if(m3u!=null)return m3u.auth();Object response;try{try{response=request(null,null,null);}catch(IOException first){if(classicHttp||first.getMessage()==null||!first.getMessage().contains("HTTP 404"))throw first;classicHttp=true;try{Object legacy=request(null,null,null);JSONObject legacyInfo=legacy instanceof JSONObject?((JSONObject)legacy).optJSONObject("user_info"):null;if(legacyInfo==null||legacyInfo.optInt("auth")!=1||!legacyInfo.optString("status","Active").equalsIgnoreCase("Active")){classicHttp=false;throw first;}response=legacy;config.put("providerHttpProfile","classic");}catch(Exception fallback){classicHttp=false;config.remove("providerHttpProfile");throw first;}}}catch(IOException denied){String m=denied.getMessage()==null?"":denied.getMessage();if(m.contains("HTTP 401"))throw new IOException("اسم المستخدم أو كلمة السر غير صحيحة. راجع بيانات الاشتراك.");if(m.contains("HTTP 403"))throw new IOException("المزوّد رفض الاتصال (HTTP 403). راجع اسم المستخدم وكلمة السر، وتأكد من رقم المنفذ في رابط السيرفر — كثير من المزودين يحتاج منفذ مثل 8080 أو 80، واترك خانة المنفذ فاضية لو المزوّد لم يعطك رقم منفذ.");throw denied;}JSONObject info=response instanceof JSONObject?((JSONObject)response).optJSONObject("user_info"):null;if(info==null||info.optInt("auth")!=1||!info.optString("status","Active").equalsIgnoreCase("Active"))throw new IOException("بيانات الاشتراك غير صحيحة أو الاشتراك غير نشط.");return new JSONObject().put("connected",true).put("name",config.optString("name","My TV")).put("expires",info.optString("exp_date","")).put("status",info.optString("status","Active")).put("activeConnections",info.optString("active_cons","")).put("maxConnections",info.optString("max_connections","")).put("live",config.optBoolean("live",true)).put("vod",config.optBoolean("vod",true)).put("series",config.optBoolean("series",true));}
 JSONArray categories(String kind)throws Exception{if(portal!=null)return portal.categories(kind);if(m3u!=null)return m3u.categories(kind);String action=kind.equals("live")?"get_live_categories":kind.equals("vod")?"get_vod_categories":"get_series_categories";Object raw=request(action,null,null);if(!(raw instanceof JSONArray))throw new IOException("المزوّد لم يرجع قائمة تصنيفات صالحة.");return (JSONArray)raw;}
 String providerImage(String value){if(value==null||value.trim().isEmpty()||value.equals("null")||value.equals("N/A"))return "";try{URI u=new URI(server+"/").resolve(value.trim().replace(" ","%20"));return Arrays.asList("http","https").contains(u.getScheme())&&u.getHost()!=null?u.toString():"";}catch(Exception e){return "";}}
 String artwork(JSONObject info,String primary){if(info==null)return "";for(String field:new String[]{primary,"cover_big","cover","stream_icon","movie_image","logo","logo_url","tvg-logo","image"}){String value=providerImage(info.optString(field,""));if(!value.isEmpty())return value;}return "";}
 static String youtubeId(String value){
  if(value==null)return "";
  String v=value.trim();
  if(v.matches("[A-Za-z0-9_-]{11}"))return v;
  try{
   String work=v;
   if(!work.matches("(?i)^[a-z][a-z0-9+.-]*://.*"))work="https://"+work;
   URI u=new URI(work);
   String host=u.getHost()==null?"":u.getHost().toLowerCase(java.util.Locale.ROOT);
   if(!Arrays.asList("youtube.com","www.youtube.com","m.youtube.com","music.youtube.com","youtu.be","youtube-nocookie.com","www.youtube-nocookie.com").contains(host))return "";
   if(host.equals("youtu.be")){String p=u.getPath();if(p!=null&&p.matches("/[A-Za-z0-9_-]{11}(/.*)?"))return p.substring(1,12);return "";}
   String path=u.getPath()==null?"":u.getPath();
   java.util.regex.Matcher m=java.util.regex.Pattern.compile("/(?:embed|shorts|live|v)/([A-Za-z0-9_-]{11})(?:[/?#]|$)").matcher(path);
   if(m.find())return m.group(1);
   String q=u.getRawQuery()==null?"":u.getRawQuery();
   m=java.util.regex.Pattern.compile("(?:^|&)v=([A-Za-z0-9_-]{11})(?:&|$)").matcher(q);
   if(m.find())return m.group(1);
  }catch(Exception ignored){}
  return "";
 }
 static String providerRating(JSONObject info,String fallback){if(info==null)return fallback;for(String field:new String[]{"rating","rating_5based"}){String raw=info.optString(field,"").trim().replace(',','.');java.util.regex.Matcher match=java.util.regex.Pattern.compile("^([0-9]+(?:\\.[0-9]+)?)(?:\\s*/\\s*(5|10))?$").matcher(raw);if(!match.matches())continue;try{double n=Double.parseDouble(match.group(1)),max=match.group(2)!=null?Double.parseDouble(match.group(2)):field.equals("rating")?10:5;if(n>0&&n<=max)return String.valueOf(n*10/max);}catch(NumberFormatException ignored){}}return fallback;}
 private final Map<String,String> artworkMemory=new LinkedHashMap<>();
 synchronized String rememberImage(String kind,String id,String image){String key=kind+":"+id;if(image!=null&&!image.isEmpty()){artworkMemory.put(key,image);while(artworkMemory.size()>2048)artworkMemory.remove(artworkMemory.keySet().iterator().next());return image;}return artworkMemory.containsKey(key)?artworkMemory.get(key):"";}
 String wideArtwork(JSONObject item){Object raw=item.opt("backdrop_path");String wide=raw instanceof JSONArray?((JSONArray)raw).optString(0):item.optString("backdrop_path",item.optString("backdrop",""));return providerImage(wide);}
 /** Preview retains only visible rows while scanning the complete provider catalog. */
  JSONObject preview(String kind,String category,int limit)throws Exception{
   if(portal!=null){JSONObject page=portal.listPage(kind,category,1);JSONArray rows=page.getJSONArray("rows");int total=page.optInt("total",rows.length());JSONArray out=new JSONArray();for(int i=0;i<Math.min(limit,rows.length());i++)out.put(rows.getJSONObject(i));return new JSONObject().put("rows",out).put("total",total);}
   if(m3u!=null){JSONArray all=m3u.list(kind,category);JSONArray out=new JSONArray();for(int i=0;i<Math.min(limit,all.length());i++)out.put(all.getJSONObject(i));return new JSONObject().put("rows",out).put("total",all.length());}
   ProviderCatalog.Result result=streamCatalog(kind,category,limit);return new JSONObject().put("rows",result.rows).put("total",result.total).put("totalExact",result.complete).put("hasMore",!result.complete);}
 JSONArray list(String kind,String category)throws Exception{if(portal!=null)return portal.list(kind,category);if(m3u!=null)return m3u.list(kind,category);return streamCatalog(kind,category,0).rows;}

 JSONArray episodes(String id)throws Exception{if(portal!=null)return portal.episodes(id);if(m3u!=null)return new JSONArray();if(!id.matches("[0-9]{1,14}"))throw new IOException("Invalid series");Object raw=request("get_series_info","series_id",id);if(!(raw instanceof JSONObject))throw new IOException("Episodes unavailable");JSONArray rows=normalizeEpisodes((JSONObject)raw);JSONObject info=((JSONObject)raw).optJSONObject("info");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);row.put("seriesId",id).put("category",id).put("seriesName",info==null?"":info.optString("name",""));}return rows;}
 JSONArray normalizeEpisodes(JSONObject raw)throws Exception{Object source=raw.opt("episodes");JSONObject groups=source instanceof JSONObject?(JSONObject)source:new JSONObject();if(source instanceof JSONArray){JSONArray flat=(JSONArray)source;for(int i=0;i<flat.length();i++){JSONObject row=flat.optJSONObject(i);if(row==null)continue;String season=row.optString("season","1");JSONArray bucket=groups.optJSONArray(season);if(bucket==null){bucket=new JSONArray();groups.put(season,bucket);}bucket.put(row);}}
 JSONArray out=new JSONArray();List<String> keys=new ArrayList<>();Iterator<String> it=groups.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys,(a,b)->{try{return Integer.compare(Integer.parseInt(a),Integer.parseInt(b));}catch(Exception e){return a.compareTo(b);}});JSONObject series=raw.optJSONObject("info");for(String season:keys){Object value=groups.opt(season);JSONArray episodes=value instanceof JSONArray?(JSONArray)value:new JSONArray();if(value instanceof JSONObject){JSONObject keyed=(JSONObject)value;Iterator<String> ids=keyed.keys();while(ids.hasNext()){JSONObject row=keyed.optJSONObject(ids.next());if(row!=null)episodes.put(row);}}List<JSONObject> sorted=new ArrayList<>();for(int i=0;i<episodes.length();i++){JSONObject e=episodes.optJSONObject(i);if(e!=null&&e.optString("id").matches("[0-9]{1,14}"))sorted.add(e);}Collections.sort(sorted,(a,b)->Integer.compare(a.optInt("episode_num",0),b.optInt("episode_num",0)));for(int i=0;i<sorted.size();i++){JSONObject e=sorted.get(i),info=e.optJSONObject("info");if(info==null)info=new JSONObject();String episodeExt=ProviderPlayback.extension(e.optString("container_extension",""));if(episodeExt.isEmpty())episodeExt=ProviderPlayback.extension(info.optString("container_extension",""));String episodeDirect=ProviderPlayback.direct(server,e.optString("direct_source",""));if(episodeDirect.isEmpty())episodeDirect=ProviderPlayback.direct(server,info.optString("direct_source",""));playbackHints.put(server,"episode",e.optString("id"),episodeExt,episodeDirect,System.currentTimeMillis());String icon=artwork(info,"movie_image");if(icon.isEmpty()&&series!=null)icon=artwork(series,"cover");out.put(new JSONObject().put("id",e.optString("id")).put("name","S"+season+" · "+e.optString("title","Episode "+(i+1))).put("season",e.optString("season",season)).put("episode",e.optInt("episode_num",i+1)).put("kind","episode").put("ext",episodeExt.isEmpty()?"mp4":episodeExt).put("icon",icon).put("duration",info.optString("duration","")).put("plot",info.optString("plot","")).put("rating",providerRating(info,providerRating(e,""))));}}return out;}

 JSONObject details(JSONObject item)throws Exception{if(portal!=null)return new JSONObject(item.toString());if(m3u!=null)return new JSONObject(item.toString());
  String kind=item.optString("kind"),id=item.optString("id");JSONObject result=new JSONObject(item.toString());
  if(!id.matches("[0-9]{1,14}")||!Arrays.asList("vod","series").contains(kind))return result;
  Object raw=request(kind.equals("vod")?"get_vod_info":"get_series_info",kind.equals("vod")?"vod_id":"series_id",id);
  if(item.optString("kind").equals("series")&&raw instanceof JSONObject){JSONObject eps=((JSONObject)raw).optJSONObject("episodes");JSONArray seasons=new JSONArray();if(eps!=null){List<String> seasonKeys=new ArrayList<>();Iterator<String> si=eps.keys();while(si.hasNext())seasonKeys.add(si.next());Collections.sort(seasonKeys,(a,b)->{try{return Integer.compare(Integer.parseInt(a),Integer.parseInt(b));}catch(Exception e){return a.compareTo(b);}});for(String k:seasonKeys)seasons.put(k);}result.put("seasons",seasons);}
  JSONObject info=raw instanceof JSONObject?((JSONObject)raw).optJSONObject("info"):null;
  if(kind.equals("vod")&&raw instanceof JSONObject){JSONObject root=(JSONObject)raw,data=root.optJSONObject("movie_data");if(data==null)data=new JSONObject();String ext=ProviderPlayback.extension(data.optString("container_extension",""));if(ext.isEmpty()&&info!=null)ext=ProviderPlayback.extension(info.optString("container_extension",""));String direct=ProviderPlayback.direct(server,data.optString("direct_source",""));if(direct.isEmpty()&&info!=null)direct=ProviderPlayback.direct(server,info.optString("direct_source",""));if(direct.isEmpty())direct=ProviderPlayback.direct(server,root.optString("direct_source",""));playbackHints.put(server,"vod",id,ext,direct,System.currentTimeMillis());if(!ext.isEmpty())result.put("ext",ext);String dataTrailer=data==null?"":youtubeId(data.optString("youtube_trailer",""));if(!dataTrailer.isEmpty()&&!result.has("trailerYoutubeId"))result.put("trailerYoutubeId",dataTrailer);}
  if(info!=null){Object backdrop=info.opt("backdrop_path");String wide=backdrop instanceof JSONArray?((JSONArray)backdrop).optString(0):info.optString("backdrop_path",info.optString("backdrop",""));wide=providerImage(wide);if(!wide.isEmpty())result.put("backdrop",wide);String release=ReleaseYear.from(info);if(!release.isEmpty())result.put("year",release);result.put("rating",providerRating(info,result.optString("rating","")));String[][] fields={{"plot","plot"},{"description","plot"},{"genre","genre"},{"releaseDate","released"},{"releasedate","released"},{"release_date","released"},{"duration","duration"},{"cast","cast"},{"director","director"}};for(String[] field:fields){String value=info.optString(field[0],"");if(!value.isEmpty()&&!value.equals("null"))result.put(field[1],value.substring(0,Math.min(value.length(),2000)));}String cover=artwork(info,"movie_image");if(!cover.isEmpty())result.put("icon",cover);String infoTrailer=youtubeId(info.optString("youtube_trailer",""));if(!infoTrailer.isEmpty())result.put("trailerYoutubeId",infoTrailer);}
  return result;
 }
 static String epgText(String value){if(value==null)return "";try{byte[] bytes=java.util.Base64.getDecoder().decode(value);String text=new String(bytes,java.nio.charset.StandardCharsets.UTF_8);if(text.indexOf('\uFFFD')<0&&!text.trim().isEmpty())return text;}catch(Exception ignored){}return value;}
 JSONObject epg(String id)throws Exception{if(portal!=null)return new JSONObject().put("items",new JSONArray());if(m3u!=null)return new JSONObject().put("items",new JSONArray());if(!id.matches("[0-9]{1,14}"))throw new IOException("Invalid channel");Object raw=request("get_short_epg","stream_id",id);JSONArray rows=raw instanceof JSONObject?((JSONObject)raw).optJSONArray("epg_listings"):null,out=new JSONArray();if(rows!=null)for(int i=0;i<Math.min(32,rows.length());i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;long start=row.optLong("start_timestamp",0),end=row.optLong("stop_timestamp",row.optLong("end_timestamp",0));if(start>100000000000L)start/=1000;if(end>100000000000L)end/=1000;if(start<=0||end<=start)continue;String title=epgText(row.optString("title","")),description=epgText(row.optString("description",""));out.put(new JSONObject().put("title",title.substring(0,Math.min(title.length(),500))).put("description",description.substring(0,Math.min(description.length(),4000))).put("start",start).put("end",end));}return new JSONObject().put("items",out);}
 private JSONObject findEpisode(Object node,String id,int depth){if(depth>4)return null;if(node instanceof JSONObject){JSONObject object=(JSONObject)node;if(id.equals(object.optString("id")))return object;Iterator<String> keys=object.keys();while(keys.hasNext()){Object value=object.opt(keys.next());if(value instanceof JSONArray||value instanceof JSONObject){JSONObject found=findEpisode(value,id,depth+1);if(found!=null)return found;}}}else if(node instanceof JSONArray){JSONArray array=(JSONArray)node;for(int i=0;i<array.length();i++){JSONObject found=findEpisode(array.opt(i),id,depth+1);if(found!=null)return found;}}return null;}
 String originalStream(JSONObject item)throws Exception{if(portal!=null||m3u!=null)return "";String id=item.optString("id"),kind=item.optString("kind");if(!id.matches("[0-9]{1,14}")||!Arrays.asList("vod","episode").contains(kind))return "";String ext=playbackHints.extension(kind,id,item.optString("ext","mp4"),System.currentTimeMillis());return server+"/"+(kind.equals("vod")?"movie":"series")+"/"+enc(user)+"/"+enc(password)+"/"+id+"."+ext;}
 String resolveStream(JSONObject item)throws Exception{if(portal!=null)return portal.stream(item);if(m3u!=null)return m3u.stream(item);String id=item.optString("id"),kind=item.optString("kind"),ext=item.optString("ext","mp4");if(!id.matches("[0-9]{1,14}")||!Arrays.asList("live","vod","episode").contains(kind))throw new IOException("اختر قناة أو فيلمًا أو حلقة.");if(kind.equals("vod")){try{details(item);}catch(Exception unavailable){}}else if(kind.equals("episode")){String series=item.optString("category","");if(series.matches("[0-9]{1,14}"))try{Object raw=request("get_series_info","series_id",series);JSONObject entry=raw instanceof JSONObject?findEpisode(((JSONObject)raw).opt("episodes"),id,0):null;if(entry!=null){JSONObject info=entry.optJSONObject("info");String e=ProviderPlayback.extension(entry.optString("container_extension",""));if(e.isEmpty()&&info!=null)e=ProviderPlayback.extension(info.optString("container_extension",""));String direct=ProviderPlayback.direct(server,entry.optString("direct_source",""));if(direct.isEmpty()&&info!=null)direct=ProviderPlayback.direct(server,info.optString("direct_source",""));playbackHints.put(server,kind,id,e,direct,System.currentTimeMillis());}}catch(Exception unavailable){}}long now=System.currentTimeMillis();String direct=playbackHints.direct(kind,id,now);if(!direct.isEmpty())return direct;ext=playbackHints.extension(kind,id,ext,now);return server+"/"+(kind.equals("live")?"live":kind.equals("vod")?"movie":"series")+"/"+enc(user)+"/"+enc(password)+"/"+id+"."+(kind.equals("live")?format:ext);}
 String stream(JSONObject item)throws Exception{if(portal!=null)return portal.stream(item);if(m3u!=null)return m3u.stream(item);String id=item.optString("id"),kind=item.optString("kind");if(!id.matches("[0-9]{1,14}")||!Arrays.asList("live","vod","episode").contains(kind))throw new IOException("اختر قناة أو فيلمًا أو حلقة.");long now=System.currentTimeMillis();String direct=playbackHints.direct(kind,id,now);if(!direct.isEmpty())return direct;String ext=playbackHints.extension(kind,id,item.optString("ext","mp4"),now);return server+"/"+(kind.equals("live")?"live":kind.equals("vod")?"movie":"series")+"/"+enc(user)+"/"+enc(password)+"/"+id+"."+(kind.equals("live")?format:ext);}
}
